#include <ranges>
#include <algorithm>

auto fibonacci(int n) {
    return std::views::iota(0, n)
         | std::views::transform([](int i) {
               int a = 0, b = 1;
               for(int j = 0; j < i; ++j) {
                   int temp = a + b;
                   a = b;
                   b = temp;
               }
               return a;
           });
}

